#!/usr/bin/env bash
# Copy one profile generated by the cimantic-graphs CIMTool builders into
# src/cimprofiles/<cim version>/ and point its imports at cimprofiles. Needed until the
# CIMTool 2.3.1 builders emit cimprofiles imports themselves.
#
# usage: scripts/import_cimtool_output.sh <cim16|cim17|cim18> <Profiles/name.py> <Profiles/name.__init__.py> [package]
#   package: the directory name under the CIM version, if not the envelope name
#            (e.g. gridappsd_rc4_2021 for the rc4_2021 envelope)
set -euo pipefail

if [ $# -lt 3 ] || [ $# -gt 4 ]; then
    echo "usage: $0 <cim16|cim17|cim18> <generated .py> <generated .__init__.py> [package]" >&2
    exit 1
fi
cim_version=$1
profile_py=$2
init_py=$3
case "$cim_version" in
    cim16|cim17|cim18) ;;
    *) echo "error: CIM version must be cim16, cim17 or cim18, got '$cim_version'" >&2; exit 1 ;;
esac

# The init builder imports from cimgraph.data_profile.<envelope>.<envelope>,
# so the module must be named <envelope>.
envelope=$(sed -n 's/^ *from cimgraph\.data_profile\.\([A-Za-z0-9_]*\)\..* import.*/\1/p' "$init_py" | head -1)
if [ -z "$envelope" ]; then
    echo "error: no 'from cimgraph.data_profile.<envelope>.<envelope> import' line in $init_py" >&2
    exit 1
fi
package=${4:-$envelope}

dest="$(cd "$(dirname "$0")/.." && pwd)/src/cimprofiles/$cim_version/$package"
mkdir -p "$dest"
cp "$profile_py" "$dest/$envelope.py"
cp "$init_py" "$dest/__init__.py"
# The profile's own package first, then identity and units
sed -i -e "s/cimgraph\.data_profile\.$envelope\./cimprofiles.$cim_version.$package./g" \
       -e 's/cimgraph\.data_profile\./cimprofiles./g' "$dest/$envelope.py" "$dest/__init__.py"

echo "imported $envelope into $dest"
echo "next: uv run python -m cimprofiles.dedupe_profile_fields --check && uv run pytest"
